const d = $input.first().json.body ?? $input.first().json;

// Build caption based on country/language
const isGulf    = ['SA','AE','KW','QA','BH','OM'].includes(d.country ?? '');
const isMorocco = (d.country ?? 'MA') === 'MA';

let caption;
if (isMorocco) {
  caption = `🔥 ${d.productName} — واو ما كاينش بحالها!\nتانريكوموندوها لكل عشاق الأكل الطيب 😍`;
} else if (isGulf) {
  caption = `🔥 ${d.productName} — تجربة لا تُنسى!\nنرشحها لكل عشّاق المطبخ الأصيل 😍`;
} else {
  caption = `🔥 ${d.productName} — Incroyable!\nOn vous recommande absolument cette expérience 😍`;
}

// Price formatting
const currencyMap = { MA: 'MAD', SA: 'SAR', AE: 'AED', TN: 'TND', DZ: 'DZD' };
const currency    = currencyMap[d.country] ?? 'MAD';
const priceStr    = `${d.productPrice?.toFixed ? d.productPrice.toFixed(0) : d.productPrice} ${currency}`;

// Watermark
const watermarkOpacity = d.hasWatermark ? '0.22' : '0';

// Logo fallback to SmartRestau generic if cafe has no logo
const logoUrl = d.logoUrl || 'https://smartrestau.com/assets/logo.png';

return [{
  json: {
    // Pass through original fields
    ...d,
    // Computed fields for Creatomate
    caption,
    priceStr,
    watermarkOpacity,
    logoUrl,
  }
}];

// Creatomate returns an array of renders
const renders  = Array.isArray($input.first().json) ? $input.first().json : [$input.first().json];
const render   = renders[0];
const upstream = $('Code — Build Creatomate Payload').first().json;

return [{
  json: {
    ...upstream,
    renderId:     render.id,
    renderStatus: render.status,
    videoUrl:     render.url ?? null,
    attempts:     0,
  }
}];

const poll      = $input.first().json;
const upstream  = $('Code — Extract Render ID').first().json;
const attempts  = (upstream.attempts ?? 0) + 1;

const isDone    = poll.status === 'succeeded';
const isFailed  = poll.status === 'failed' || attempts >= 10; // max 150s wait

return [{
  json: {
    ...upstream,
    renderStatus: poll.status,
    videoUrl:     poll.url ?? upstream.videoUrl ?? null,
    attempts,
    isDone,
    isFailed,
  }
}];

